#[cfg(feature = "plans")]
#[derive(Debug, Clone, Default)]
pub struct UpdatePlanParams {
    #[doc = "Whether the plan is currently available for new subscriptions."]
    pub active: Option<bool>,
    #[doc = "Specifies which fields in the response should be expanded."]
    pub expand: Option<Vec<String>>,
    #[doc = "Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object."]
    pub metadata: Option<std::collections::HashMap<String, String>>,
    #[doc = "A brief description of the plan, hidden from customers."]
    pub nickname: Option<String>,
    #[doc = "The product the plan belongs to."]
    pub product: Option<String>,
    #[doc = "Default number of trial days when subscribing a customer to this plan using [`trial_from_plan=true`](https://docs.str..."]
    pub trial_period_days: Option<i64>,
}

#[cfg(feature = "plans")]
impl crate::params::FormEncode for UpdatePlanParams {
    fn encode_form(&self, form: &mut crate::params::FormBuilder) {
        form.field_opt("active", self.active.as_ref());
        if let Some(values) = self.expand.as_ref() {
            form.field_array("expand", values.as_slice());
        }
        if let Some(values) = self.metadata.as_ref() {
            for (key, value) in values.iter() {
                form.field_map("metadata", key, value);
            }
        }
        form.field_opt("nickname", self.nickname.as_ref());
        form.field_opt("product", self.product.as_ref());
        form.field_opt("trial_period_days", self.trial_period_days.as_ref());
    }
}

#[cfg(feature = "plans")]
#[doc = "Create a plan"]
pub async fn create_plan(
    client: &crate::Client,
    params: &crate::plans::CreatePlanParams,
) -> Result<crate::plans::Plan, crate::Error> {
    let path = crate::params::format_path("/v1/plans", &[]);
    client.post_form(&path, params).await
}

#[cfg(feature = "plans")]
#[doc = "Delete a plan"]
pub async fn delete_plan(
    client: &crate::Client,
    plan: &str,
    params: &crate::params::Empty,
) -> Result<crate::plans::DeletedPlan, crate::Error> {
    let path = crate::params::format_path("/v1/plans/{plan}", &[("plan", plan)]);
    client.delete_form(&path, params).await
}

#[cfg(feature = "plans")]
#[doc = "Retrieve a plan"]
pub async fn get_plan(
    client: &crate::Client,
    plan: &str,
    params: &crate::plans::GetPlanParams,
) -> Result<crate::plans::Plan, crate::Error> {
    let path = crate::params::format_path("/v1/plans/{plan}", &[("plan", plan)]);
    client.get(&path, params).await
}

